<script setup>
import { ref } from 'vue'
const deadzone=ref(8),outer=ref(100),preset=ref('Default Linear'),presets=['Default Linear','Instant','Smooth','0-Deadzone']
function usePreset(value){preset.value=value;deadzone.value=value==='0-Deadzone'?0:value==='Instant'?2:value==='Smooth'?12:8}
</script>
<template><section class="visual-grid stick-grid"><article v-for="side in ['Left','Right']" :key="side" class="panel-card"><div class="panel-heading"><div><span class="eyebrow">摇杆设置</span><h3>{{side}} stick</h3></div><span class="live-tag">{{preset}}</span></div><div class="stick-body"><div class="circle"><i class="zone outer"></i><i class="zone inner" :style="{width:deadzone+'%',height:deadzone+'%'}"></i><i class="axis x"></i><i class="axis y"></i><i class="stick-dot"></i></div><div class="stick-controls"><label>内死区 <b>{{deadzone}}%</b><input v-model.number="deadzone" type="range" min="0" max="40"></label><label>外死区 <b>{{outer}}%</b><input v-model.number="outer" type="range" min="60" max="100"></label><span class="eyebrow">快速预设</span><div class="preset-list"><button v-for="item in presets" :key="item" class="btn" :class="{primary:preset===item}" @click="usePreset(item)">{{item}}</button></div></div></div><div class="curve-preview"><span>Response curve</span><svg viewBox="0 0 200 70" role="img" aria-label="Response curve"><path d="M8 62 L192 8"/><path class="curve" :d="preset==='Instant'?'M8 62 Q30 62 50 49 T192 8':preset==='Smooth'?'M8 62 C65 60 90 42 192 8':'M8 62 L192 8'"/></svg></div></article></section></template>
<style scoped>.stick-grid{margin-bottom:16px}.stick-body{display:grid;grid-template-columns:180px 1fr;gap:22px;align-items:center;padding:20px 0}.circle{position:relative;width:170px;height:170px;border:1px solid #64748b;border-radius:50%;background:radial-gradient(circle,#0b1424,#0f172a);overflow:hidden}.zone{position:absolute;inset:7%;border:1px dashed #475569;border-radius:50%}.zone.inner{inset:50%;transform:translate(-50%,-50%);border:1px solid #22d3ee;background:#22d3ee22;max-width:100%;max-height:100%}.axis{position:absolute;background:#334155}.axis.x{height:1px;left:0;right:0;top:50%}.axis.y{width:1px;top:0;bottom:0;left:50%}.stick-dot{position:absolute;left:58%;top:43%;width:9px;height:9px;border-radius:50%;background:#34d399;box-shadow:0 0 12px #34d399}.stick-controls{display:grid;gap:12px}.stick-controls label{display:grid;grid-template-columns:1fr auto;gap:6px;color:#cbd5e1;font-size:11px}.stick-controls input{grid-column:1/-1;width:100%;accent-color:#22d3ee}.stick-controls b{color:#67e8f9}.preset-list{display:flex;gap:6px;flex-wrap:wrap}.preset-list .btn{font-size:9px;padding:6px 8px}.curve-preview{display:flex;align-items:center;gap:15px;border-top:1px solid #334155;padding-top:12px;color:#94a3b8;font-size:10px}.curve-preview svg{width:200px;height:70px;background:linear-gradient(135deg,transparent 49%,#334155 50%,transparent 51%);border-left:1px solid #475569;border-bottom:1px solid #475569}.curve-preview path{fill:none;stroke:#475569;stroke-width:1}.curve-preview path.curve{stroke:#22d3ee;stroke-width:3}@media(max-width:600px){.stick-body{grid-template-columns:1fr;justify-items:center}.stick-controls{width:100%}}</style>